package dev.jlo.gamemodes.domain.siege;
import dev.jlo.gamemodes.domain.common.Team;
import java.time.Instant;
import java.util.Objects;
public final class SiegeKeg { private final String id; private final Team owner; private final Instant armedAt; private final boolean destroyed,disarmed; public SiegeKeg(String id,Team owner,Instant armedAt){this(id,owner,armedAt,false,false);} public SiegeKeg(String id,Team owner,Instant armedAt,boolean destroyed,boolean disarmed){this.id=id;this.owner=owner;this.armedAt=armedAt;this.destroyed=destroyed;this.disarmed=disarmed;} public String getId(){return id;} public Team getOwner(){return owner;} public Instant getArmedAt(){return armedAt;} public boolean getDestroyed(){return destroyed;} public boolean getDisarmed(){return disarmed;} public SiegeKeg copy(String id,Team owner,Instant armedAt,boolean destroyed,boolean disarmed){return new SiegeKeg(id,owner,armedAt,destroyed,disarmed);} public SiegeKeg copy(boolean destroyed,boolean disarmed){return new SiegeKeg(id,owner,armedAt,destroyed,disarmed);}@Override public boolean equals(Object o){return this==o||(o instanceof SiegeKeg x&&destroyed==x.destroyed&&disarmed==x.disarmed&&Objects.equals(id,x.id)&&owner==x.owner&&Objects.equals(armedAt,x.armedAt));}@Override public int hashCode(){return Objects.hash(id,owner,armedAt,destroyed,disarmed);}@Override public String toString(){return "SiegeKeg(id="+id+", owner="+owner+", armedAt="+armedAt+", destroyed="+destroyed+", disarmed="+disarmed+")";} }
